CREATE TABLE music_import (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,attachment_id UUID NOT NULL,track_id UUID, status VARCHAR(24) NOT NULL,error_code VARCHAR(128),error_message VARCHAR(512),idempotency_key VARCHAR(256) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(attachment_id) REFERENCES attachment(id),FOREIGN KEY(track_id) REFERENCES music_track(id),UNIQUE(owner_id,idempotency_key));
